var GENRES_VARIETY = ['\u771F\u4EBA\u79C0', '\u8131\u53E3\u79C0', '\u9009\u79C0', '\u97F3\u4E50', '\u65C5\u884C', '\u559C\u5267'];
var GENRES_DOCUMENTARY = ['\u5386\u53F2', '\u81EA\u7136', '\u793E\u4F1A', '\u4EBA\u7269', '\u6218\u4E89', '\u97F3\u4E50', '\u4F20\u8BB0', '\u72AF\u7F6A'];
var GENRES_ANIME = ['\u70ED\u8840', '\u5192\u9669', '\u5947\u5E7B', '\u79D1\u5E7B', '\u641E\u7B11', '\u604B\u7231', '\u6821\u56ED', '\u6CBB\u6108', '\u60AC\u7591', '\u63A8\u7406', '\u65E5\u5E38', '\u8FD0\u52A8', '\u673A\u6218', '\u50AC\u6CEA'];
