var REGIONS_MOVIE = ['\u534E\u8BED', '\u4E2D\u56FD\u5927\u9646', '\u4E2D\u56FD\u9999\u6E2F', '\u4E2D\u56FD\u53F0\u6E7E', '\u97E9\u56FD', '\u65E5\u672C', '\u6CF0\u56FD', '\u5370\u5EA6', '\u6B27\u7F8E', '\u7F8E\u56FD', '\u82F1\u56FD', '\u6CD5\u56FD', '\u5FB7\u56FD', '\u610F\u5927\u5229', '\u897F\u73ED\u7259', '\u4FC4\u7F57\u65AF', '\u52A0\u62FF\u5927', '\u6FB3\u5927\u5229\u4E9A'];
