        '2': [['\u5168\u90E8', ''], ['\u56FD\u4EA7\u5267', '12'], ['\u9999\u6E2F\u5267', '13'], ['\u53F0\u6E7E\u5267', '14'], ['\u6B27\u7F8E\u5267', '15'], ['\u65E5\u672C\u5267', '16'], ['\u97E9\u56FD\u5267', '17'], ['\u6D77\u5916\u5267', '18'], ['\u6CF0\u56FD\u5267', '19'], ['\u65B0\u52A0\u5761\u5267', '69']],
        '3': [['\u5168\u90E8', ''], ['\u4E2D\u56FD\u52A8\u6F2B', '30'], ['\u65E5\u672C\u52A8\u6F2B', '31'], ['\u6B27\u7F8E\u52A8\u6F2B', '33']],
