        const collapsed = collapsedCards.has(key);
        const toggleText = collapsed ? '\u5C55\u5F00\u5206\u96C6\uFF08'+pages.length+'\uFF09' : '\u6536\u8D77\u5206\u96C6';
        const toggle = '<button class="episode load-eps toggle-eps" data-key="'+escapeHtml(key)+'">'+escapeHtml(toggleText)+'</button>';
