    async function renderSites() {
      setMessage('\u6B63\u5728\u8BFB\u53D6\u7AD9\u6E90\u5217\u8868...');
      $('detailBody').innerHTML = '<div class="status">\u7AD9\u6E90\u52A0\u8F7D\u4E2D...</div>';
      try {
        const result = await api('/website/api/sites');
        editingSites = Array.isArray(result.data) ? result.data : [];
        renderSiteEditor(0, { keepVisible: false });
      } catch (error) {
        handleError(error);
      }
    }

    function renderSiteEditor(selected, options) {
      const opts = options || {};
      const enabled = editingSites.filter(site => site.enable !== false).length;
      setMessage('\u5F53\u524D\u542F\u7528 ' + enabled + ' / ' + editingSites.length + ' \u4E2A\u7AD9\u6E90\uFF0C\u4FDD\u5B58\u540E /config \u4F1A\u6309\u8FD9\u91CC\u7684\u987A\u5E8F\u8F93\u51FA\u3002');
      $('detailBody').innerHTML =
        actions([['enableAllSites','\u5168\u90E8\u542F\u7528','secondary'],['disableAllSites','\u5168\u90E8\u505C\u7528','ghost'],['resetSites','\u91CD\u7F6E','danger'],['saveSites','\u4FDD\u5B58','primary']]) +
        '<div class="site-list">' + editingSites.map((site, index) => siteRowHtml(site, index, selected)).join('') + '</div>';
      document.querySelectorAll('[data-site-toggle]').forEach((node) => {
        node.onchange = () => {
          const index = Number(node.dataset.index);
          if (!editingSites[index]) return;
          editingSites[index].enable = node.checked;
          renderSiteEditor(index);
        };
      });
      document.querySelectorAll('[data-site-up]').forEach((node) => node.onclick = () => moveSite(Number(node.dataset.index), -1));
      document.querySelectorAll('[data-site-down]').forEach((node) => node.onclick = () => moveSite(Number(node.dataset.index), 1));
      bindSiteDragEvents();
      $('enableAllSites').onclick = () => setAllSites(true);
      $('disableAllSites').onclick = () => setAllSites(false);
      $('resetSites').onclick = resetSites;
      $('saveSites').onclick = saveSites;
      if (opts.keepVisible !== false) focusSiteRow(selected);
    }

    function siteRowHtml(site, index, selected) {
      const cls = ['site-row'];
      if (site.enable === false) cls.push('disabled');
      if (index === selected) cls.push('selected');
      return '<div class="' + cls.join(' ') + '" data-index="' + index + '">' +
        '<div class="site-drag" title="\u6309\u4F4F\u62D6\u52A8\u6392\u5E8F" data-site-drag data-index="' + index + '" draggable="true"><span class="site-drag-mark">::</span><span>\u62D6\u52A8\u6392\u5E8F</span></div>' +
        '<label class="site-toggle"><input type="checkbox" data-site-toggle data-index="' + index + '" ' + (site.enable !== false ? 'checked' : '') + '><span>\u542F\u7528</span></label>' +
        '<div class="site-main"><div class="site-name">' + escapeHtml(site.name || site.key) + '</div><div class="site-meta">' + (index + 1) + '. ' + escapeHtml(site.key) + ' \xB7 ' + siteTypeName(site.type) + '</div></div>' +
        '<div class="site-move"><button data-site-up data-index="' + index + '" ' + (index <= 0 ? 'disabled' : '') + '>\u4E0A</button><button data-site-down data-index="' + index + '" ' + (index >= editingSites.length - 1 ? 'disabled' : '') + '>\u4E0B</button></div>' +
        '</div>';
    }

    function moveSite(index, step) {
      const next = index + step;
      if (next < 0 || next >= editingSites.length) return;
      const item = editingSites[index];
      editingSites[index] = editingSites[next];
      editingSites[next] = item;
      renderSiteEditor(next);
    }

    function bindSiteDragEvents() {
      document.querySelectorAll('.site-row').forEach((row) => {
        row.ondragstart = (event) => {
          draggingSiteIndex = Number(row.dataset.index);
          row.classList.add('dragging');
          if (event.dataTransfer) {
            event.dataTransfer.effectAllowed = 'move';
            event.dataTransfer.setData('text/plain', String(draggingSiteIndex));
          }
        };
        row.ondragend = () => {
          draggingSiteIndex = -1;
          document.querySelectorAll('.site-row').forEach(item => item.classList.remove('dragging','drag-over'));
        };
        row.ondragover = (event) => {
          event.preventDefault();
          const target = Number(row.dataset.index);
          if (target !== draggingSiteIndex) row.classList.add('drag-over');
          if (event.dataTransfer) event.dataTransfer.dropEffect = 'move';
        };
        row.ondragleave = () => row.classList.remove('drag-over');
        row.ondrop = (event) => {
          event.preventDefault();
          row.classList.remove('drag-over');
          const from = draggingSiteIndex >= 0 ? draggingSiteIndex : Number(event.dataTransfer && event.dataTransfer.getData('text/plain'));
          const to = Number(row.dataset.index);
          moveSiteTo(from, to);
        };
      });
    }

    function moveSiteTo(from, to) {
      if (from < 0 || from >= editingSites.length || to < 0 || to >= editingSites.length || from === to) return;
      const item = editingSites.splice(from, 1)[0];
      editingSites.splice(to, 0, item);
      draggingSiteIndex = -1;
      renderSiteEditor(to);
    }

    function focusSiteRow(index) {
      setTimeout(() => {
        const row = document.querySelector('.site-row[data-index="' + index + '"]');
        if (!row) return;
        row.scrollIntoView({ block: 'center', inline: 'nearest' });
      }, 0);
    }

    function setAllSites(enable) {
      editingSites = editingSites.map(site => Object.assign({}, site, { enable }));
      renderSiteEditor(0);
    }

    async function saveSites() {
      await api('/website/api/sites',{method:'PUT',body:JSON.stringify({list: editingSites})});
      toast('\u7AD9\u6E90\u8BBE\u7F6E\u5DF2\u4FDD\u5B58');
      await renderSites();
    }

    async function resetSites() {
      await api('/website/api/sites',{method:'DELETE'});
      toast('\u7AD9\u6E90\u8BBE\u7F6E\u5DF2\u91CD\u7F6E');
      await renderSites();
    }

    function siteTypeName(type) {
      const value = Number(type || 3);
      if (value < 10) return '\u89C6\u9891';
      if (value < 20) return '\u9605\u8BFB';
      if (value < 30) return '\u6F2B\u753B';
      if (value < 40) return '\u97F3\u4E50';
      if (value < 50) return '\u7F51\u76D8';
      return '\u5176\u4ED6';
    }

    function renderSettings() {
      const proxyText = state.proxyMode === 'smart' ? '\u4F18\u5316\u4EE3\u7406\u6A21\u5F0F' : '\u517C\u5BB9\u4EE3\u7406\u6A21\u5F0F';
      setMessage((state.showTranscode ? '\u5F53\u524D\uFF1A\u663E\u793A\u6781\u901F\u7EBF\u8DEF' : '\u5F53\u524D\uFF1A\u9690\u85CF\u6781\u901F\u7EBF\u8DEF') + ' \xB7 ' + (state.autoDanmaku === false ? '\u81EA\u52A8\u5F39\u5E55\u5173\u95ED' : '\u81EA\u52A8\u5F39\u5E55\u5F00\u542F') + ' \xB7 ' + proxyText + ' \xB7 ' + (state.smartProxyLog ? '\u4EE3\u7406\u65E5\u5FD7\u5F00\u542F' : '\u4EE3\u7406\u65E5\u5FD7\u5173\u95ED'));
      $('detailBody').innerHTML = '<label><input id="showTranscode" type="checkbox" style="width:auto;height:auto;margin-right:8px" ' + (state.showTranscode ? 'checked' : '') + '>\u663E\u793A\u6781\u901F\u7EBF\u8DEF</label>' +
        '<label><input id="autoDanmaku" type="checkbox" style="width:auto;height:auto;margin-right:8px" ' + (state.autoDanmaku === false ? '' : 'checked') + '>\u81EA\u52A8\u63A8\u9001\u5F39\u5E55</label>' +
        '<label>\u7F51\u76D8\u64AD\u653E\u4EE3\u7406\u6A21\u5F0F<select id="proxyMode"><option value="legacy"' + (state.proxyMode === 'smart' ? '' : ' selected') + '>\u517C\u5BB9\u6A21\u5F0F</option><option value="smart"' + (state.proxyMode === 'smart' ? ' selected' : '') + '>\u4F18\u5316\u6A21\u5F0F</option></select></label>' +
        '<label><input id="smartProxyLog" type="checkbox" style="width:auto;height:auto;margin-right:8px" ' + (state.smartProxyLog ? 'checked' : '') + '>\u4F18\u5316\u4EE3\u7406\u65E5\u5FD7</label>' +
        '<div class="actions"><button class="ghost" id="refreshStatus">\u91CD\u65B0\u68C0\u6D4B\u72B6\u6001</button></div>';
      $('showTranscode').onchange = async () => {
        const enabled = $('showTranscode').checked;
        await api('/website/api/settings/transcode',{method:'PUT',body:JSON.stringify({enabled})});
        toast(enabled ? '\u5DF2\u663E\u793A\u6781\u901F\u7EBF\u8DEF' : '\u5DF2\u9690\u85CF\u6781\u901F\u7EBF\u8DEF');
        await refresh();
      };
      $('autoDanmaku').onchange = async () => {
        const enabled = $('autoDanmaku').checked;
        await api('/website/api/settings/auto-danmaku',{method:'PUT',body:JSON.stringify({enabled})});
        toast(enabled ? '\u5DF2\u5F00\u542F\u81EA\u52A8\u5F39\u5E55' : '\u5DF2\u5173\u95ED\u81EA\u52A8\u5F39\u5E55');
        await refresh();
      };
      $('proxyMode').onchange = async () => {
        const mode = $('proxyMode').value;
        await api('/website/api/settings/proxy-mode',{method:'PUT',body:JSON.stringify({mode})});
        toast(mode === 'smart' ? '\u5DF2\u5207\u6362\u4F18\u5316\u4EE3\u7406\u6A21\u5F0F' : '\u5DF2\u5207\u6362\u517C\u5BB9\u4EE3\u7406\u6A21\u5F0F');
        await refresh();
      };
      $('smartProxyLog').onchange = async () => {
        const enabled = $('smartProxyLog').checked;
        await api('/website/api/settings/smart-proxy-log',{method:'PUT',body:JSON.stringify({enabled})});
        toast(enabled ? '\u5DF2\u5F00\u542F\u4F18\u5316\u4EE3\u7406\u65E5\u5FD7' : '\u5DF2\u5173\u95ED\u4F18\u5316\u4EE3\u7406\u65E5\u5FD7');
        await refresh();
      };
      $('refreshStatus').onclick = refresh;
    }

    function renderOrder() {
      editingOrder = state.panPriority.split(',').filter(id => id !== 'direct');
      setMessage('\u9884\u89C8\u987A\u5E8F\uFF1A' + editingOrder.map(nameOf).join(' > '));
      $('detailBody').innerHTML = '<div class="order-editor"><select id="panOrderSelect" size="9"></select><div class="side-actions">' +
        '<button id="moveUp">\u4E0A\u79FB</button><button id="moveDown">\u4E0B\u79FB</button><button id="resetOrder">\u9ED8\u8BA4</button><button class="primary" id="saveOrder">\u4FDD\u5B58</button>' +
        '</div></div>';
      updateOrderSelect(0);
      $('moveUp').onclick = () => moveOrder(-1);
      $('moveDown').onclick = () => moveOrder(1);
      $('resetOrder').onclick = () => {
        editingOrder = ['quark','uc','baidu','pan115','pan123','pan189','new139','guangya','thunder'];
        updateOrderSelect(0);
      };
      $('saveOrder').onclick = async () => {
        await api('/website/api/settings/pan-priority',{method:'PUT',body:JSON.stringify({priority: editingOrder.concat(['direct']).join(',')})});
        toast('\u7F51\u76D8\u6392\u5E8F\u5DF2\u4FDD\u5B58');
        await refresh();
      };
    }

    function renderBackup() {
      const dav = (secrets && secrets.backup && secrets.backup.webdav) || {};
      const davStatus = (state && state.backup && state.backup.webdav) || {};
      setMessage('\u5BFC\u51FA\u6216\u5BFC\u5165 wexfnwconfig.json\u3002WebDAV \u5907\u4EFD\u8DEF\u5F84\uFF1A/wexfnw/wexfnwconfig.json\u3002');
      $('detailBody').innerHTML =
        '<div class="status">\u5BFC\u51FA\u4F1A\u5728\u4E0B\u65B9\u663E\u793A\u5F53\u524D\u914D\u7F6E\u5185\u5BB9\uFF1B\u6062\u590D\u5907\u4EFD\u8BF7\u9009\u62E9 wexfnwconfig.json \u6587\u4EF6\u3002</div>' +
        '<input id="dbFile" type="file" accept=".json,application/json" style="display:none">' +
        actions([['exportDb','\u5BFC\u51FA\u914D\u7F6E','primary'],['copyDb','\u590D\u5236\u914D\u7F6E','secondary'],['downloadDbBtn','\u4E0B\u8F7D\u6587\u4EF6','ghost'],['selectDb','\u9009\u62E9\u914D\u7F6E\u6062\u590D','danger']]) +
        '<div class="status">WebDAV\uFF1A' + escapeHtml(davStatus.configured ? ('\u5DF2\u914D\u7F6E ' + (davStatus.server || '')) : '\u672A\u914D\u7F6E') + '</div>' +
        '<div class="row">' + input('webDavServer','WebDAV \u5730\u5740',dav.server) + input('webDavUser','\u7528\u6237\u540D',dav.user) + '</div>' +
        '<div><label for="webDavPass">\u5BC6\u7801</label><input id="webDavPass" type="password" value="' + escapeHtml(dav.pass || '') + '"></div>' +
        '<div class="status" id="webDavTips">\u586B\u5199 WebDAV \u5730\u5740\u3001\u7528\u6237\u540D\u3001\u5BC6\u7801\u540E\uFF0C\u5148\u70B9\u201C\u6D4B\u8BD5\u8FDE\u63A5\u201D\uFF1B\u5907\u4EFD\u4F1A\u4E0A\u4F20\u5230 /wexfnw/wexfnwconfig.json\uFF0C\u6062\u590D\u4F1A\u8986\u76D6\u5F53\u524D\u672C\u5730\u914D\u7F6E\u3002</div>' +
        actions([['saveWebDavBackup','\u4FDD\u5B58WebDAV','primary'],['testWebDavBackup','\u6D4B\u8BD5\u8FDE\u63A5','secondary'],['runWebDavBackup','WebDAV\u5907\u4EFD','primary'],['runWebDavRestore','WebDAV\u6062\u590D','danger'],['clearWebDavBackup','\u6E05\u9664WebDAV','ghost']]) +
        '<textarea id="dbExportText" placeholder="\u70B9\u51FB\u5BFC\u51FA\u914D\u7F6E\u540E\u663E\u793A\u5185\u5BB9" style="min-height:260px"></textarea>';
      $('exportDb').onclick = exportDbText;
      $('copyDb').onclick = copyDbText;
      $('downloadDbBtn').onclick = () => downloadDb();
      $('selectDb').onclick = () => $('dbFile').click();
      $('dbFile').onchange = importDbFile;
      $('saveWebDavBackup').onclick = saveWebDavBackup;
      $('testWebDavBackup').onclick = testWebDavBackup;
      $('runWebDavBackup').onclick = runWebDavBackup;
      $('runWebDavRestore').onclick = runWebDavRestore;
      $('clearWebDavBackup').onclick = clearWebDavBackup;
    }

    function webDavBackupPayload() {
      return {
        server: $('webDavServer').value,
        user: $('webDavUser').value,
        pass: $('webDavPass').value
      };
    }

    async function saveWebDavBackup() {
      await runWebDavAction('\u6B63\u5728\u4FDD\u5B58 WebDAV \u914D\u7F6E...', async () => {
        await api('/website/api/backup/webdav',{method:'PUT',body:JSON.stringify(webDavBackupPayload())});
        toast('WebDAV \u914D\u7F6E\u5DF2\u4FDD\u5B58');
        await refresh();
        return 'WebDAV \u914D\u7F6E\u5DF2\u4FDD\u5B58\uFF0C\u53EF\u4EE5\u7EE7\u7EED\u6D4B\u8BD5\u8FDE\u63A5\u6216\u76F4\u63A5\u5907\u4EFD\u3002';
      });
    }

    async function testWebDavBackup() {
      await runWebDavAction('\u6B63\u5728\u6D4B\u8BD5 WebDAV \u8FDE\u63A5...', async () => {
        await api('/website/api/backup/webdav/test',{method:'POST',body:JSON.stringify(webDavBackupPayload())});
        toast('WebDAV \u8FDE\u63A5\u6B63\u5E38');
        return 'WebDAV \u8FDE\u63A5\u6B63\u5E38\uFF0C\u8FDC\u7A0B\u76EE\u5F55 /wexfnw \u53EF\u7528\u3002';
      });
    }

    async function runWebDavBackup() {
      await runWebDavAction('\u6B63\u5728\u4E0A\u4F20\u914D\u7F6E\u5230 WebDAV...', async () => {
        await api('/website/api/backup/webdav/backup',{method:'POST',body:JSON.stringify(webDavBackupPayload())});
        toast('WebDAV \u5907\u4EFD\u5B8C\u6210');
        await refresh();
        return 'WebDAV \u5907\u4EFD\u5B8C\u6210\uFF1A/wexfnw/wexfnwconfig.json\u3002';
      });
    }

    let webDavRestoreConfirmUntil = 0;

    async function runWebDavRestore() {
      const now = Date.now();
      const btn = $('runWebDavRestore');
      if (now > webDavRestoreConfirmUntil) {
        webDavRestoreConfirmUntil = now + 10000;
        if (btn) btn.textContent = '\u786E\u8BA4\u6062\u590D';
        setWebDavTips('\u518D\u6B21\u70B9\u51FB\u201C\u786E\u8BA4\u6062\u590D\u201D\u5C06\u4ECE WebDAV \u8986\u76D6\u5F53\u524D\u672C\u5730\u914D\u7F6E\u3002');
        toast('\u8BF7\u518D\u6B21\u70B9\u51FB\u786E\u8BA4\u6062\u590D');
        return;
      }
      webDavRestoreConfirmUntil = 0;
      await runWebDavAction('\u6B63\u5728\u4ECE WebDAV \u6062\u590D\u914D\u7F6E...', async () => {
        await api('/website/api/backup/webdav/restore',{method:'POST',body:JSON.stringify(webDavBackupPayload())});
        toast('WebDAV \u914D\u7F6E\u5DF2\u6062\u590D');
        await refresh();
        return 'WebDAV \u914D\u7F6E\u5DF2\u6062\u590D\uFF0C\u5F53\u524D\u8BBE\u7F6E\u5DF2\u91CD\u65B0\u52A0\u8F7D\u3002';
      });
    }

    async function clearWebDavBackup() {
      await runWebDavAction('\u6B63\u5728\u6E05\u9664\u672C\u5730\u4FDD\u5B58\u7684 WebDAV \u914D\u7F6E...', async () => {
        await api('/website/api/backup/webdav',{method:'DELETE'});
        toast('WebDAV \u914D\u7F6E\u5DF2\u6E05\u9664');
        await refresh();
        return '\u672C\u5730\u4FDD\u5B58\u7684 WebDAV \u914D\u7F6E\u5DF2\u6E05\u9664\uFF0C\u8FDC\u7A0B\u5907\u4EFD\u6587\u4EF6\u4E0D\u4F1A\u88AB\u5220\u9664\u3002';
      });
    }

    async function runWebDavAction(tip, action) {
      setWebDavTips(tip);
      try {
        const done = await action();
        setWebDavTips(done || 'WebDAV \u64CD\u4F5C\u5B8C\u6210');
      } catch (error) {
        const text = error && error.message ? error.message : String(error || 'WebDAV \u64CD\u4F5C\u5931\u8D25');
        setWebDavTips(text, true);
        throw error;
      }
    }

    function setWebDavTips(text, bad) {
      const node = $('webDavTips');
      if (node) {
        node.className = 'status ' + (bad ? 'bad' : '');
        node.textContent = text || '';
      }
      setMessage(text, bad);
    }

    async function renderQuarkLog() {
      setMessage('\u8BFB\u53D6\u5938\u514B\u64AD\u653E\u94FE\u8DEF\u65E5\u5FD7...');
      $('detailBody').innerHTML = '<div class="status">\u65E5\u5FD7\u52A0\u8F7D\u4E2D...</div>';
      try {
        const list = (await api('/website/api/quark-play-logs')).data || [];
        const current = list[0] && list[0].name ? list[0].name : ('quark-play-' + new Date().toISOString().slice(0,10) + '.log');
        const log = (await api('/website/api/quark-play-logs/' + encodeURIComponent(current))).data || {};
        setMessage(log.truncated ? '\u53EA\u663E\u793A\u6700\u8FD1 256KB \u65E5\u5FD7' : '\u663E\u793A\u5F53\u524D\u65E5\u5FD7');
        $('detailBody').innerHTML =
          '<div><label for="quarkLogFile">\u65E5\u5FD7\u6587\u4EF6</label><select id="quarkLogFile">' +
          (list.length ? list.map(item => '<option value="' + escapeHtml(item.name) + '" ' + (item.name === current ? 'selected' : '') + '>' + escapeHtml(item.name) + ' \xB7 ' + formatBytes(item.size) + '</option>').join('') : '<option value="' + current + '">' + current + '</option>') +
          '</select></div>' +
          actions([['reloadQuarkLog','\u5237\u65B0','secondary'],['copyQuarkLog','\u590D\u5236\u65E5\u5FD7','primary'],['clearQuarkLog','\u6E05\u7A7A\u65E5\u5FD7','danger']]) +
          '<pre id="quarkLogText" style="white-space:pre-wrap;word-break:break-all;max-height:520px;overflow:auto;background:#07111f;border:1px solid var(--line);border-radius:8px;padding:12px;font-size:12px;line-height:1.5">' + escapeHtml(log.text || '\u6682\u65E0\u5938\u514B\u64AD\u653E\u65E5\u5FD7') + '</pre>';
        $('quarkLogFile').onchange = renderSelectedQuarkLog;
        $('reloadQuarkLog').onclick = renderSelectedQuarkLog;
        $('copyQuarkLog').onclick = copyQuarkLog;
        $('clearQuarkLog').onclick = clearSelectedQuarkLog;
      } catch (error) {
        handleError(error);
      }
    }

    async function renderSelectedQuarkLog() {
      const quarkLogFile = $('quarkLogFile');
      const file = quarkLogFile ? quarkLogFile.value : '';
      const log = (await api('/website/api/quark-play-logs/' + encodeURIComponent(file))).data || {};
      setMessage(log.truncated ? '\u53EA\u663E\u793A\u6700\u8FD1 256KB \u65E5\u5FD7' : '\u663E\u793A\u5F53\u524D\u65E5\u5FD7');
      $('quarkLogText').textContent = log.text || '\u6682\u65E0\u5938\u514B\u64AD\u653E\u65E5\u5FD7';
    }

    async function copyQuarkLog() {
      const quarkLogText = $('quarkLogText');
      const text = quarkLogText ? quarkLogText.textContent : '';
      if (!text || text === '\u6682\u65E0\u5938\u514B\u64AD\u653E\u65E5\u5FD7') return toast('\u6CA1\u6709\u53EF\u590D\u5236\u7684\u65E5\u5FD7');
      await navigator.clipboard.writeText(text);
      toast('\u65E5\u5FD7\u5DF2\u590D\u5236');
    }

    async function clearSelectedQuarkLog() {
      const quarkLogFile = $('quarkLogFile');
      const file = quarkLogFile ? quarkLogFile.value : '';
      await api('/website/api/quark-play-logs/' + encodeURIComponent(file), { method:'DELETE' });
      toast('\u5938\u514B\u65E5\u5FD7\u5DF2\u6E05\u7A7A');
      await renderQuarkLog();
    }

    async function saveCredential(provider, field, value, shouldRefresh = true) {
      await api('/website/api/credential/' + provider + '/' + field,{method:'PUT',body:JSON.stringify({value})});
      if (shouldRefresh) {
        toast('\u5DF2\u4FDD\u5B58');
        await refresh();
      }
    }
    async function exportDbText() {
      const result = await api('/website/api/db/json');
      const text = JSON.stringify(result.data || {}, null, 2);
      const textarea = $('dbExportText');
      if (textarea) textarea.value = text;
      setMessage('\u914D\u7F6E\u5DF2\u5BFC\u51FA\u5230\u4E0B\u65B9\u6587\u672C\u6846\u3002');
      toast('\u914D\u7F6E\u5DF2\u5BFC\u51FA');
    }
    async function copyDbText() {
      const textarea = $('dbExportText');
      let text = textarea ? textarea.value : '';
      if (!text) {
        const result = await api('/website/api/db/json');
        text = JSON.stringify(result.data || {}, null, 2);
        if (textarea) textarea.value = text;
      }
      if (!text) return toast('\u6CA1\u6709\u53EF\u590D\u5236\u7684\u914D\u7F6E');
      await navigator.clipboard.writeText(text);
      toast('\u914D\u7F6E\u5DF2\u590D\u5236');
    }
    async function importDbFile(event) {
      const input = event ? event.target : null;
      const file = input && input.files ? input.files[0] : null;
      if (!file) return;
      try {
        const text = await file.text();
        const data = JSON.parse(text || '{}');
        if (!data || typeof data !== 'object' || Array.isArray(data)) throw new Error('wexfnwconfig.json \u5185\u5BB9\u683C\u5F0F\u4E0D\u6B63\u786E');
        await api('/website/api/db',{method:'POST',body:JSON.stringify(data)});
        toast('\u914D\u7F6E\u5DF2\u5BFC\u5165');
        await refresh();
      } finally {
        if (input) input.value = '';
      }
    }
    async function clearCredential(provider, field) {
      await api('/website/api/credential/' + provider + '/' + field,{method:'DELETE'});
      toast('\u5DF2\u6E05\u9664');
      await refresh();
    }
